-- Mantem somente a ata de menor ID quando a carga anterior inseriu a mesma ata mais de uma vez.
DELETE duplicada FROM ata_registro_preco duplicada INNER JOIN (SELECT numero, ano, MIN(id) AS id_mantido FROM ata_registro_preco GROUP BY numero, ano HAVING COUNT(*) > 1) repetida ON repetida.numero = duplicada.numero AND repetida.ano = duplicada.ano AND repetida.id_mantido <> duplicada.id;

